 refuge(){this.venom=0;this.idle=0;this.large=null;this.q().antidotes=3;state.hearts=5;persist();hud();const d=this.q().desert;show(`<h2 id="panel-title">Shade beside the survey post</h2><p>Rested. Three antidotes and five road hearts restored. Nothing hunts you in this refuge.</p><p><strong>${d.completed.length}/6 distinct far-side readings</strong>. This visit began at the ${esc(d.entry)} edge; the far side is ${esc(this.opposite(d.entry))}.</p><p>${d.completed.map(i=>esc(this.names[i])).join(' · ')||'The six measures are still unrecorded.'}</p><div class="actions"><button class="primary" data-action="close">Continue the crossing</button><button data-action="q16-road-home">Call a caravan to Woodland</button></div>`,'q16-refuge','THE SIX REACHES');},
